// Matches each word to a YSO term through Finto, the National Library of
// Finland's public vocabulary service. Only an exact name counts: the
// preferred name, or another name YSO lists for the same term (jatkuva
// oppiminen is filed under elinikäinen oppiminen). The article's language is
// tried first, then Finnish, English and Swedish, because a thesis written in
// English carries English terms. One call at a time.
const UA = 'DFP newsletter bot (HAMK student project)';
const pause = ms => new Promise(resolve => setTimeout(resolve, ms));
// URLSearchParams is not available in n8n's Code node.
const query = o => Object.entries(o).map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&');
const found = [];
let error = null;

for (const w of $json.words || []) {
  let match = null;
  try {
    for (const lang of [...new Set([w.lang, 'fi', 'en', 'sv'])]) {
      const data = await this.helpers.httpRequest({
        url: 'https://api.finto.fi/rest/v1/yso/search?' + query({ query: w.label, lang, labellang: 'fi' }),
        json: true, timeout: 15000,
        headers: { 'User-Agent': UA, Accept: 'application/json' },
      });
      const same = s => String(s || '').toLowerCase() === w.label;
      match = (data.results || []).find(r => r.uri && r.prefLabel &&
        ((lang === 'fi' && same(r.prefLabel)) || same(r.matchedPrefLabel) || same(r.altLabel) || same(r.hiddenLabel)));
      if (match) break;
      await pause(100);
    }
  } catch (e) {
    // Finto is away. What was matched so far is kept; the rest waits for the
    // next run.
    error = `Finto did not answer: ${e.message}`;
    break;
  }
  found.push({ label: w.label, uri: match ? match.uri : null, name: match ? match.prefLabel : null });
  await pause(100);
}
return [{ json: { found, error } }];

// Finto AI is the National Library's subject indexing service: given a
// Finnish text, it suggests YSO terms with a score from 0 to 1. It is free
// and open, and asks that calls are not made in parallel, so these go one at
// a time. Only the title and our own Finnish summary are sent.
const UA = 'DFP newsletter bot (HAMK student project)';
const pause = ms => new Promise(resolve => setTimeout(resolve, ms));
const minScore = Number($json.min_score) || 0.1;
// URLSearchParams is not available in n8n's Code node.
const form = o => Object.entries(o).map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&');
const done = [];
let error = null;

for (const a of $json.articles || []) {
  try {
    const data = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://ai.finto.fi/v1/projects/yso-fi/suggest',
      body: form({ text: a.text, limit: 10, threshold: minScore }),
      headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'User-Agent': UA, Accept: 'application/json' },
      json: true, timeout: 30000,
    });
    const terms = (data.results || [])
      .filter(r => r.uri && r.label && Number(r.score) >= minScore)
      .map((r, n) => ({ uri: r.uri, label: r.label, score: Number(r.score), rank: n + 1 }));
    done.push({ id: a.id, terms, error: null });
  } catch (e) {
    const status = Number(e.httpCode || (e.response && e.response.status) || e.statusCode || 0);
    // An answer of 4xx is about this text: written down and tried again in an
    // hour. No answer at all means the service is away: stop here, and the
    // next run, 15 minutes later, starts again with the same summaries.
    if (status >= 400 && status < 500) {
      done.push({ id: a.id, terms: [], error: `Finto AI answered ${status}` });
      continue;
    }
    error = `Finto AI did not answer: ${e.message}`;
    break;
  }
  await pause(200);
}
return [{ json: { done, error } }];
